/* Accessibility: Hide radio but keep it functional for screen readers if custom styled, 
   but here I'll keep the native radio visible for simplicity and robustness, 
   just styled with accent-color. */

const { useState } = React;

const RadioButton = ({ id, label, value, checked, onChange }) => {
  return (
    <label className={`radio-option ${checked ? 'selected' : ''}`} htmlFor={id}>
      <input
        type="radio"
        id={id}
        name="notification-preference"
        value={value}
        checked={checked}
        onChange={() => onChange(value)}
      />
      <span className="radio-label">{label}</span>
    </label>
  );
};

const NotificationForm = () => {
  const [preference, setPreference] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (preference) {
      alert(`Preference saved: ${preference}`);
    } else {
      alert('Please select a notification preference.');
    }
  };

  const options = [
    { id: 'email', label: 'Email', value: 'email' },
    { id: 'sms', label: 'SMS', value: 'sms' },
    { id: 'push', label: 'Push Notifications', value: 'push' }
  ];

  return (
    <div className="card">
      <h1>Notification Settings</h1>
      <form onSubmit={handleSubmit}>
        <div className="form-field">
          <fieldset style={{ border: 'none', padding: 0, margin: 0 }}>
            <legend className="field-label">How do you prefer to receive notifications?</legend>
            <div className="radio-group">
              {options.map((option) => (
                <RadioButton
                  key={option.id}
                  id={option.id}
                  label={option.label}
                  value={option.value}
                  checked={preference === option.value}
                  onChange={setPreference}
                />
              ))}
            </div>
          </fieldset>
        </div>
        <button type="submit" className="submit-btn">
          Save Preference
        </button>
      </form>
    </div>
  );
};

const App = () => {
  return <NotificationForm />;
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);

